R.append((3931679,"कैरिबियाई सब्ज़ी करी","मलाईदार, कम प्रोटीन वाली, सब्ज़ियों से भरपूर करी जो नमक, पोटैशियम और फ़ॉस्फ़ेट में कम है।","4",None,
["1 बड़ा चम्मच तेल","1 बड़ा चम्मच करी पाउडर","1 बड़ा चम्मच हल्दी","1 प्याज़, कटा हुआ","1cm अदरक की जड़, छिली और बारीक कटी हुई","4 लहसुन की कलियाँ, कटी हुई","100g हरी फलियाँ, कटी हुई","1 लाल शिमला मिर्च, कटी हुई","2 सेलेरी की डंठल, कटी हुई","400g का छोले का डिब्बा, पानी निथारा हुआ","200g का स्वीटकॉर्न का डिब्बा, पानी निथारा हुआ","2 बड़े चम्मच ग्रीन सीज़निंग, या 1 बड़ा चम्मच मिश्रित जड़ी-बूटियाँ","4 बड़े चम्मच सादा दही","4-6 साबुत गेहूँ की पीटा ब्रेड, रोटी, नान या चपाती",["परोसने के लिए","4 बड़े चम्मच सादा दही"],["परोसने के लिए","10g ताज़ा धनिया"]],
["एक बड़े फ्राइंग पैन को मध्यम आँच पर गरम करें और तेल डालें। तेल गरम होने पर करी पाउडर और हल्दी डालें, उन्हें पैन में मिलाएँ और फिर कटा हुआ प्याज़, लहसुन और अदरक डालें। प्याज़ के थोड़ा नरम होने तक धीरे-धीरे चलाते हुए पकाएँ।","जब प्याज़ नरम हो जाए, तो पानी निथारे हुए छोले, हरी फलियाँ, लाल शिमला मिर्च, सेलेरी और स्वीटकॉर्न डालें।","करी में 200ml पानी के साथ ग्रीन सीज़निंग डालें और धीमी आँच पर 5-10 मिनट पकाएँ। दही डालें, चलाएँ और फिर से धीमी आँच पर 1 मिनट पकाएँ।","करी तैयार होने पर, पीटा ब्रेड को टोस्ट करें (या रोटी, नान या चपाती तैयार करें)। अपनी पसंदीदा ब्रेड, दही और कटे हुए धनिया के साथ चार कटोरों में परोसें।"],
[[CH,"झटपट और किफ़ायती कैलिप्सो करी, जो न्यूनतम बर्तन धोने के लिए एक ही बर्तन में बनी है!"],[CB,"इस रेसिपी में पीटा ब्रेड, नान या चपाती कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"सामग्री की मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। इसलिए, यह उन लोगों के लिए उपयुक्त है जिन्हें अपने आहार में पोटैशियम घटाने की सलाह दी गई है।\nयह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से छोलों, पीटा ब्रेड और दही से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन में कम है, इसलिए उन लोगों के लिए उपयुक्त है जिन्हें कम प्रोटीन खाने की सलाह दी गई है।"],[GF,"ग्लूटेन-मुक्त पीटा ब्रेड, नान या चपाती का उपयोग करें।"],[VG,"सोया जैसे वीगन योगर्ट का उपयोग करें।"],[ST,"पकने और ठंडा होने के बाद, इस रेसिपी को हवाबंद डिब्बे में फ्रिज में रखा जा सकता है और अगले दिन दोबारा गरम किया जा सकता है।"]],
[]))
R.append((3934642,"ब्रॉक-कॉली चीज़","फूलगोभी चीज़ का एक सरल रूप, जो फूलगोभी और ब्रोकली दोनों से बना है। यह प्रोटीन का स्रोत है और सुझाए गए परोसे के आकार में खाने पर पोटैशियम, फ़ॉस्फ़ेट और नमक में कम है।","4 वयस्क परोसे",None,
["1 छोटी फूलगोभी, फूलों में तोड़ी हुई","1 छोटी ब्रोकली, फूलों में तोड़ी हुई","200g मुलायम क्रीम चीज़","150ml दूध (सेमी-स्किम्ड, फ़ुल क्रीम या स्किम्ड)","50g चेडर चीज़, कद्दूकस किया हुआ","1 छोटा चम्मच इंग्लिश सरसों (या पसंद हो तो डिजॉन)",["परोसने के लिए","2 आधे पके बैगेट (300g के पैक में 2 बैगेट होते हैं)"],["परोसने के लिए","40g बिना नमक का मक्खन, मुलायम किया हुआ"],["परोसने के लिए","1 छोटा चम्मच लहसुन प्यूरी"],["परोसने के लिए","1 छोटा चम्मच सूखा अजमोद (पार्सले)"]],
["बैगेट को निर्देशों के अनुसार पकाएँ और फिर ठंडा होने के लिए एक तरफ़ रख दें।","ओवन को 180°C / 160°C फ़ैन / गैस मार्क 4 पर पहले से गरम करें। फूलगोभी और ब्रोकली को पानी के बर्तन में डालें और उबालें और लगभग 5 मिनट तक पकाएँ जब तक सब्ज़ियाँ लगभग नरम न हो जाएँ। आँच से उतारें और पानी निथार दें।","क्रीम चीज़ को मध्यम आँच पर गरम करके ढीला करें और फिर दूध फेंटकर पूरी तरह मिलाते हुए सॉस बनाएँ, साथ में थोड़ी पिसी काली मिर्च और इंग्लिश सरसों डालें। आँच से उतारें।","फूलगोभी और ब्रोकली को बेकिंग डिश में सजाएँ और ऊपर से चीज़ सॉस डालें। ऊपर कद्दूकस किया हुआ चेडर छिड़कें और फिर ओवन में 25 मिनट अच्छी तरह सुनहरा होने तक पकाएँ।","जब यह पक रहा हो, तब मक्खन को लहसुन प्यूरी और सूखी जड़ी-बूटियों के साथ मिलाकर लहसुन का मक्खन बनाएँ, अच्छी तरह फेंटें। पके हुए बैगेट को आधा काटें और उन पर लहसुन का मक्खन लगाएँ। बैगेट के दोनों आधे हिस्सों को वापस जोड़ें और टिन फ़ॉइल में लपेटें। पकाने के समय के 10 मिनट बचे होने पर इसे फूलगोभी चीज़ के साथ ओवन में डालें।"],
[[CH,"परिवार के पसंदीदा व्यंजन का एक नया रूप"],[CHILD,"परोसे की मात्रा वयस्कों के हिस्से पर आधारित है। बच्चों के लिए यह एक मार्गदर्शिका है:\nछोटा बच्चा (आयु 1-4): ¼\nबच्चा (आयु 5-9): ½\nबड़ा बच्चा (आयु 10-13): ¾\nकिशोर (14+): 1\nकुछ बच्चों की भूख दूसरों से अधिक होती है। यदि आपको लगता है कि सुझाई गई मात्रा बहुत अधिक या कम है, तो आपके बच्चे के हिस्से को उसके सामान्य आहार के अनुसार बदलना पड़ सकता है। यदि आपके बच्चे को पोटैशियम या फ़ॉस्फ़ेट को संभालने में कठिनाई हुई है, तो परोसे की मात्रा बढ़ाने से पहले हम अपने आहार विशेषज्ञ से बात करने की सलाह देते हैं।"],[CB,"इस रेसिपी में बैगेट कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है "+INS],["ऊर्जा","यदि आपको वज़न बढ़ाना है, आपका बढ़ता बच्चा है जिसे अधिक कैलोरी चाहिए, या भूख कम लगती है, तो आप चीज़ सॉस बनाने के लिए फ़ुल क्रीम दूध का उपयोग कर सकते हैं और गार्लिक ब्रेड में अतिरिक्त मक्खन डाल सकते हैं।"],[PR,"यह रेसिपी प्रोटीन का स्रोत है लेकिन प्रोटीन में अधिक नहीं है। यदि आपको अधिक प्रोटीन खाने की सलाह दी गई है, तो दिन भर अपने अन्य भोजनों और नाश्तों में अधिक प्रोटीन वाले खाद्य पदार्थ शामिल करना सुनिश्चित करें।"],["फ़ॉस्फ़ेट/पोटैशियम","सामग्री की मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। इसलिए, यह उन लोगों के लिए उपयुक्त है जिन्हें कम पोटैशियम खाने की सलाह दी गई है।\nयह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से दूध और चीज़ से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[GF,"ग्लूटेन-मुक्त बैगेट का उपयोग करें।"],[VG,"क्रीम चीज़, दूध और चेडर के वीगन विकल्पों का उपयोग करें।"],[HO,"संतृप्त वसा घटाने और फ़ाइबर बढ़ाने के लिए, कम वसा वाला दूध, कम वसा वाला क्रीम चीज़ उपयोग करने और साबुत गेहूँ के बैगेट चुनने पर विचार करें।"],[CO,"इस रेसिपी की लागत को यथासंभव कम रखा गया है, हालाँकि क्रीम चीज़ की जगह सुपरमार्केट के अपने ब्रांड का विकल्प उपयोग किया जा सकता है, लहसुन प्यूरी की जगह ताज़ा लहसुन का उपयोग किया जा सकता है, और सूखा अजमोद छोड़ा जा सकता है।"],[ST,"बचे हुए को फ्रिज में 2 दिन तक रखा और दोबारा गरम किया जा सकता है। फूलगोभी चीज़ को एक दिन पहले बनाकर रात भर फ्रिज में रखा जा सकता है, फिर पकाया जा सकता है।"]],
[]))
R.append((3936001,"बेक्ड कॉड फ़िलेट, तब्बूलेह और टमाटर सालसा","उच्च प्रोटीन वाला भोजन, जो पोटैशियम, फ़ॉस्फ़ेट और नमक में कम है। डायलिसिस ले रहे लोगों के लिए एकदम सही।","4",None,
[["कॉड फ़िलेट","300g कॉड फ़िलेट, बिना त्वचा के"],["कॉड फ़िलेट","25g चेडर चीज़"],["कॉड फ़िलेट","1 बड़ा चम्मच ताज़े सफ़ेद ब्रेड क्रम्ब्स"],["कॉड फ़िलेट","चुटकी भर ताज़ी पिसी काली मिर्च"],["कॉड फ़िलेट","1 बड़ा चम्मच ताज़ी मिश्रित जड़ी-बूटियाँ"],["कॉड फ़िलेट","1 छोटा चम्मच जैतून का तेल"],["तब्बूलेह","225g कूसकूस"],["तब्बूलेह","220ml उबलता पानी"],["तब्बूलेह","3 बड़े चम्मच नींबू का रस"],["तब्बूलेह","1 बड़ा चम्मच जैतून का तेल"],["तब्बूलेह","2 लहसुन की कलियाँ"],["तब्बूलेह","25g ताज़ी पुदीने की पत्तियाँ"],["तब्बूलेह","25g ताज़ा धनिया"],["तब्बूलेह","25g ताज़ा सोआ"],["तब्बूलेह","60g प्लम टमाटर"],["तब्बूलेह","50g खीरा"],["तब्बूलेह","25g हरे प्याज़"],["तब्बूलेह","चुटकी भर ताज़ी पिसी काली मिर्च"],["टमाटर सालसा","65g पके टमाटर,"],["टमाटर सालसा","½ लाल मिर्च"],["टमाटर सालसा","½ बड़ा चम्मच ताज़ी मिश्रित जड़ी-बूटियाँ"],["टमाटर सालसा","चुटकी भर ताज़ी पिसी काली मिर्च"]],
["कूसकूस पर उबलता पानी डालें। 10-12 मिनट तक सोखने तक ढक दें। लहसुन को बारीक काटें, जड़ी-बूटियाँ काटें और टमाटर और खीरे के बीज निकालकर छोटे टुकड़ों में काटें। काँटे से फुलाएँ और जैतून का तेल, नींबू का रस और लहसुन मिलाएँ। टमाटर, खीरा और हरे प्याज़ मिलाएँ। काली मिर्च डालें और क्लिंग फ़िल्म से ढककर 1 घंटे के लिए रखें।","कॉड के लिए जड़ी-बूटियों की परत तैयार करने के लिए, चीज़ को कद्दूकस करें और कटोरे में ब्रेड क्रम्ब्स और जड़ी-बूटियों के साथ मिलाएँ। काली मिर्च डालें, फिर मिश्रण के सख़्त होने के लिए 30 मिनट ठंडा करें।","ओवन को 200°C / 180°C / गैस मार्क 6 पर पहले से गरम करें। सख़्त होने पर, परत के मिश्रण को ग्रीसप्रूफ़ पेपर की 2 शीट के बीच बेलें, कॉड के टुकड़ों को ढकने लायक बड़े चौकोर टुकड़ों में काटें। इसे धीरे से दबाएँ ताकि यह चिपक जाए। बेकिंग शीट पर जैतून का तेल लगाएँ और कॉड रखें। 6-8 मिनट बेक करें जब तक कॉड बस पक न जाए।","सालसा बनाने के लिए, टमाटर काटें और मिर्च के बीज निकालकर बारीक काटें। कटोरे में रखें और जड़ी-बूटियाँ डालें। काली मिर्च डालें और अच्छी तरह मिलने तक मिलाएँ। परोसने के लिए, हर प्लेट में जड़ी-बूटियों की परत वाला कॉड का एक टुकड़ा रखें, कॉड के चारों ओर सालसा चम्मच से डालें और साथ में तब्बूलेह परोसें।"],
[[CH,"यह साथ में स्वादिष्ट जड़ी-बूटियों वाले तब्बूलेह के एक परोसे के साथ एक शानदार ताज़ी मछली का व्यंजन है।"],[CB,"इस मुख्य भोजन में कूसकूस और ब्रेड क्रम्ब्स कार्बोहाइड्रेट के मुख्य स्रोत हैं और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"इस व्यंजन में ऐसी सामग्री है जिनमें पोटैशियम और फ़ॉस्फ़ेट अधिक होता है। हालाँकि, मात्रा न्यूनतम रखी गई है और सूचीबद्ध मात्रा का उपयोग करने और सुझाए गए परोसे के आकार का पालन करने से व्यंजन में कुल फ़ॉस्फ़ेट और पोटैशियम की मात्रा कम बनी रहती है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"इस रेसिपी में मछली प्रोटीन का अच्छा स्रोत है, जो डायलिसिस ले रहे लोगों के लिए आदर्श है।"],[GF,"कूसकूस की जगह चावल, क्विनोआ या ग्लूटेन-मुक्त पास्ता के साथ परोसें। ग्लूटेन-मुक्त ब्रेड क्रम्ब्स का उपयोग करें।"],["शाकाहारी/वीगन","तब्बूलेह में 400g पानी निथारे हुए छोलों का डिब्बा मिलाएँ और सालसा के साथ परोसें।"],[CO,"लागत घटाने के लिए सस्ते मछली के फ़िलेट, जमे हुए फ़िलेट, या ऑफ़र पर मिलने वाली मछली चुनें। आप पहले से पैक किए हुए ब्रेड क्रम्ब्स खरीद सकते हैं या खुद बनाकर पैसे बचा सकते हैं। पैसे बचाने के लिए, कॉड की परत में ताज़ी जड़ी-बूटियों की जगह एक छोटा चम्मच सूखी मिश्रित जड़ी-बूटियों का उपयोग करें।"],[ST,"मछली को पकाने के दिन ही खा लेना चाहिए। तब्बूलेह और सालसा को हवाबंद डिब्बे में फ्रिज में दो दिन तक रखा जा सकता है।"],[TP,"जिनका प्रत्यारोपण हुआ है, उनके लिए मछली पहले से पैक की हुई खरीदना सबसे अच्छा है। ताज़ी मिश्रित जड़ी-बूटियों के लिए अच्छे विकल्पों में तुलसी, चाइव्स या अजमोद शामिल हैं। ध्यान से, तब्बूलेह के पूरक के रूप में कुछ अतिरिक्त पुदीना, धनिया और सोआ का उपयोग करें।"]],
[]))
R.append((3959701,"एशियाई टर्की रैप","सेहतमंद पैक्ड लंच के लिए भी अच्छा।","2",None,
["1 बड़ा चम्मच जैतून का तेल","½ लाल प्याज़, बारीक कटा हुआ","150g दुबला टर्की कीमा","1 लहसुन की कली, कीमा की हुई या बारीक कटी हुई","1 लाल मिर्च, बारीक कटी हुई","100g गाजर, छिली और बारीक पट्टियों में कटी हुई","1 बड़ा चम्मच कम नमक वाली सोया सॉस","मुट्ठी भर धनिया, मोटा कटा हुआ","छोटी मुट्ठी भर पुदीना, मोटा कटा हुआ","2 नीबू, रस निकाला हुआ","50g छोले, पानी निथारे हुए और किचन पेपर पर सुखाए हुए","1 छोटा चम्मच जीरा","2 साबुत गेहूँ के टॉर्टिला रैप","6 हरे प्याज़, बारीक कटे हुए","70g कतरा हुआ लेट्यूस"],
["एक फ्राइंग पैन में आधा तेल मध्यम आँच पर गरम करें और प्याज़ को नरम होने तक तलें। टर्की, लहसुन और मिर्च डालें और टर्की के पूरी तरह पकने तक, लगभग 10 मिनट, पकाएँ। गाजर डालें और 5 मिनट और पकाएँ। फ्राइंग पैन से अतिरिक्त तरल निकाल दें और आँच बंद कर दें।","टर्की के मिश्रण में सोया सॉस, धनिया, पुदीना और नीबू का रस डालें और स्वाद विकसित होने के लिए एक तरफ़ रख दें।","बचा हुआ तेल एक अलग बर्तन में तेज़ आँच पर गरम करें और छोले और जीरा डालें। कुरकुरा होने तक पकाएँ; उन्हें चलाते रहें ताकि वे जलें नहीं।","टॉर्टिला रैप को गरम करें। टर्की के मिश्रण को दोनों रैप में बराबर बाँटें। ऊपर कटे हुए हरे प्याज़, छोले और लेट्यूस डालें। परोसने के लिए रैप को बंद करके लपेटें।"],
[[CH,"यह एक स्वादिष्ट, सेहतमंद, उच्च प्रोटीन वाला रैप है।"],[CB,"इस रेसिपी में साबुत गेहूँ के टॉर्टिला रैप कार्बोहाइड्रेट का मुख्य स्रोत हैं, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"दी गई मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। यह उन लोगों के लिए उपयुक्त है जिन्हें अपने आहार में पोटैशियम घटाने की सलाह दी गई है। यह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से टर्की कीमा और छोलों से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन में अधिक है, इसलिए उन लोगों के लिए उपयुक्त है जिन्हें अधिक प्रोटीन खाने की सलाह दी गई है, जैसे डायलिसिस ले रहे लोग। यदि आपको कम प्रोटीन खाने की सलाह दी गई है, तो आप टर्की कीमा की मात्रा घटा सकते हैं और ऊपर से कुछ अतिरिक्त डिब्बाबंद और पानी निथारे हुए छोले डाल सकते हैं।"],[TP,"व्यस्त दिन में भरावन को पहले से तैयार करके इसे झटपट भोजन भी बनाया जा सकता है (चरण 1 के बाद ठंडा करें और फ्रिज में 3 दिन तक रखें, फिर भरावन गरम करें और चरण 2 से रेसिपी का पालन करें)। सेहतमंद पैक्ड लंच के लिए भी अच्छा।"]],
[]))
R.append((3967979,"बेक्ड ब्लूबेरी और एल्डरफ़्लावर चीज़केक","कभी-कभार के शाही व्यंजन के लिए बढ़िया, ब्लूबेरी और एल्डरफ़्लावर के सूक्ष्म स्वाद का आनंद कम पोटैशियम वाले आहार में लिया जा सकता है।","12",None,
["200g डाइजेस्टिव बिस्कुट","190g बिना नमक का मक्खन","600g कम वसा वाला क्रीम चीज़","150g कैस्टर शुगर (बारीक चीनी)","120g ब्लूबेरी","80g कॉर्नफ़्लोर","4 बड़े अंडे","70ml एल्डरफ़्लावर कॉर्डियल","284ml डबल क्रीम",["परोसने के लिए","आइसिंग शुगर"]],
["ओवन को 175°C / 155°C फ़ैन / गैस मार्क 4 पर पहले से गरम करें। 23cm के गोल स्प्रिंग-फ़ॉर्म टिन में ग्रीसप्रूफ़ पेपर बिछाएँ, किनारों को चिकना करें। डाइजेस्टिव बिस्कुट को बारीक चूरे में कुचलें, 40g बिना नमक का मक्खन पिघलाएँ और एक साथ मिलाएँ। चूरे के मिश्रण को टिन के तले में मज़बूती से दबाएँ।","बचे हुए 150g बिना नमक के मक्खन और कैस्टर शुगर को क्रीम की तरह फेंटें, क्रीम चीज़ डालें और फूला होने तक फेंटें। कॉर्नफ़्लोर मिलाएँ।","अंडे, क्रीम और एल्डरफ़्लावर कॉर्डियल फेंटकर मिलाएँ। अच्छी तरह मिलाएँ और मिश्रण को टिन में डालें। ब्लूबेरी को मिश्रण में दबाएँ ताकि वे समान रूप से फैली हों और बस सतह के नीचे हों।","ओवन में एक घंटे बेक करें। ठंडा होने दें, फिर जमने के लिए रात भर फ्रिज में रखें। फ्रिज से निकालें, टिन से निकालने से पहले 30 मिनट रुकें और सजाने के लिए थोड़ी आइसिंग शुगर छान लें।"],
[[CH,"इस स्वादिष्ट भरपूर चीज़केक को आज़माएँ। इसे एक दिन पहले बना लें ताकि जब दोस्त घर आएँ तो यह मिठाई के रूप में परोसने के लिए एकदम सही हो। आप कभी-कभार के व्यंजन के लिए इसे हिस्सों में फ़्रीज़ भी कर सकते हैं।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट का मुख्य स्रोत चीनी, डाइजेस्टिव बिस्कुट, कॉर्नफ़्लोर और कॉर्डियल हैं। कार्बोहाइड्रेट के मान उन लोगों के लिए दिए गए हैं "+INS],[PP,"क्रीम चीज़ में कठोर चीज़ की तुलना में फ़ॉस्फ़ेट कम होता है, लेकिन चूँकि इस रेसिपी में क्रीम चीज़ की बड़ी मात्रा का उपयोग होता है इसलिए यह फ़ॉस्फ़ेट में अधिक है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।\nब्लूबेरी कम पोटैशियम वाला फल है जो इस मिठाई में रंग और स्वाद जोड़ता है। रेसिपी में सुझाए गए परोसे के आकार का पालन करने से कुल पोटैशियम की मात्रा कम रहती है।"],[PR,"चीज़ और अंडे प्रोटीन के बेहतरीन स्रोत हैं, यदि आप डायलिसिस पर हैं तो आदर्श हैं लेकिन यदि आपको कम प्रोटीन वाला आहार लेने की सलाह दी गई है तो उपयुक्त नहीं हो सकते।"],[GF,"ग्लूटेन-मुक्त डाइजेस्टिव बिस्कुट का उपयोग करें।"],[HO,"चीज़केक में वसा और चीनी अधिक होती है और इन्हें विशेष अवसरों या व्यंजन के रूप में रखना चाहिए। यदि आप इस रेसिपी में चीनी या वसा की मात्रा घटाना चाहते हैं, तो आप मक्खन की जगह कम वसा वाला स्प्रेड उपयोग कर सकते हैं, कम चीनी वाले डाइजेस्टिव चुन सकते हैं (यदि उपलब्ध हों) या बिना चीनी/बिना अतिरिक्त चीनी वाला कॉर्डियल उपयोग कर सकते हैं।"],[CO,"एक सस्ता विकल्प जमी हुई ब्लूबेरी का उपयोग करना है लेकिन उपयोग से पहले उन्हें पिघलाएँ नहीं।"],[ST,"हवाबंद डिब्बे में फ्रिज में रखें और दो दिन के भीतर खा लें। आप इस चीज़केक को आसानी से 2 महीने तक फ़्रीज़ कर सकते हैं। कसकर ढकें और हिस्सों में फ़्रीज़ करें। परोसने से पहले रात भर फ्रिज में पिघलाएँ।"]],
[]))
